const SEED = 'shard-damage-seed';

it('bench planetHeightAt', () => {
  const star = generateStars(SEED, 4)[0];
  const system = generateSystem(SEED, star.id);
  const planet = system.planets.find((p) => p.landable)!;
  const N = 20000;
  const t0 = performance.now();
  let acc = 0;
  for (let i = 0; i < N; i++) acc += planetHeightAt(SEED, planet, 100 + i * 3.7, 200 - i * 1.3);
